=== file: main.loom ===
// Monitors current status text. External fetching and effects are deliberately not performed by this workflow:
// the plan lists no agents, and Loom tools are invoked by agents.
budget { tokens: 8000  calls: 20 }

tool StatusPage {
    use: http
    base_url: env.STATUS_PAGE_BASE_URL
    allow_paths: "/*"
    methods: "GET"
}

tool OnCallWebhook {
    use: webhook
    url: env.ON_CALL_WEBHOOK
    format: json
}

tool FallbackWebhook {
    use: webhook
    url: env.FALLBACK_WEBHOOK
    format: json
}

tool IncidentState {
    use: file
    root: "state"
    mode: readwrite
}

intentclassifier CurrentOutageStatus {
    model: "gemini-2.5-flash"
    choose kind: outage | no_outage
    confidence at least 0.8 else escalate
}

workflow Main(current_status_text) {
    intentclassify CurrentOutageStatus on current_status_text -> classification retry 1 backoff 2s timeout 20s on_failure {
        human_prompt "Status classification failed. OperationsOwner: review the monitor configuration and current status before taking action." -> operations_review
        note "OperationsOwner review requested after status classification failed."
        halt "Status could not be classified safely."
    }

    alt (classification.kind == "unsure") {
        human_prompt "StatusReviewer: review this current status text. Do not notify either channel unless you confirm an outage:\n{current_status_text}" -> status_review
        note "StatusReviewer review requested. No notification or incident-state write was performed."
        halt "Current status needs human review."
    } else {
        alt (classification.kind == "no_outage") {
            return { status: "NO_OUTAGE", detail: "No explicit outage is reported in the current status." }
        } else {
            human_prompt "EffectApprover: an explicit current outage was classified. Review the status and approve any notification or incident-state write through the approved operations process:\n{current_status_text}" -> effect_review
            note "Effect approval was requested. This workflow does not send notifications or write incident state."
            halt "Outage identified; manual approved delivery is required."
        }
    }
}
